import{_ as o,o as r,c as e,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-06-20 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-06-20 :: Ceph Performance Meeting","date":"2019-06-20T00:00:00.000Z","updated":"2019-06-21T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","蓝存储","垃圾回收","安全模式"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-06-20_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-06-20_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780459816000}'),s={name:"posts/2019/2019-06-20_-_-_Ceph_Performance_Meeting.md"};function l(g,t,i,p,a,_){return r(),e("div",null,[...t[0]||(t[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年6月20日</p><p><strong>参会人员</strong>： 多位Ceph研发人员</p><p><strong>会议主题</strong>： Ceph项目性能优化讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、新功能请求</strong></p><ol><li><strong>蓝星缓存改进</strong>： 讨论了蓝星缓存的多个功能请求，包括缓存性能优化和popup history功能，旨在提高缓存效率和反映缓存情况。</li><li><strong>Peachy映射缓存</strong>： 已合并，用于存储给定OST映射的重算计算，显著提高了性能。</li><li><strong>优化对象创建操作</strong>： 一个优化对象创建操作的PR即将合并，可以跳过Blue Store中的查找，提高效率。</li></ol><p><strong>二、垃圾回收</strong></p><ol><li><strong>垃圾回收性能</strong>： 讨论了垃圾回收的性能问题，并提出了改进建议。</li></ol><p><strong>三、Blue Store/Orcs关闭</strong></p><ol><li><strong>Stan和Pat</strong>： 正在努力关闭Blue Store或Orcs。</li></ol><p><strong>四、其他讨论</strong></p><ol><li><strong>能量消耗</strong>： 讨论了能量消耗问题，并提出了改进建议。</li><li><strong>性能提升</strong>： 讨论了性能提升问题，并提出了改进建议。</li><li><strong>恢复操作优化</strong>： 讨论了恢复操作的优化问题，并提出了自适应恢复的方案。</li><li><strong>安全模式</strong>： 讨论了安全模式的使用和性能影响，并提出了性能测试和优化建议。</li><li><strong>全闪存性能</strong>： 讨论了全闪存性能问题，并提出了改进建议。</li></ol><p><strong>五、后续行动计划</strong></p><ol><li><strong>性能测试</strong>： 进行安全模式的性能测试，并分析性能影响。</li><li><strong>优化代码</strong>： 优化垃圾回收、安全模式和全闪存性能相关的代码。</li><li><strong>自适应恢复实现</strong>： 实现自适应恢复功能。</li><li><strong>性能分析</strong>： 使用性能分析工具分析性能瓶颈。</li></ol><p><strong>六、其他</strong></p><ol><li>会议中提到了一些其他问题，如日志性能、锁竞争等，并提出了改进建议。</li></ol><p><strong>总结</strong>：</p><p>本次会议重点讨论了Ceph项目的性能优化，包括蓝星缓存、垃圾回收、安全模式、自适应恢复等功能。会议确定了后续行动计划，并要求相关人员完成相关工作，以进一步提升Ceph的性能和稳定性。</p>',19)])])}const h=o(s,[["render",l]]);export{d as __pageData,h as default};
